'use strict';
(async()=>{
 const auth=document.getElementById('auth'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const config=globalThis.CF_CLOUD_CONFIG||{},id=config.googleClientId;
 const load=src=>new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=()=>reject(Error('Não foi possível carregar '+src));document.head.append(s)});
 const fail=err=>{const el=document.getElementById('cloudError');if(el)el.textContent=err.message;else auth.textContent=err.message};
 const intro='<div class="eyebrow">CENTRAL FINANCEIRA • V4 • GOOGLE DRIVE</div><h1>Seu cofre financeiro</h1><p>Os dados são criptografados neste dispositivo antes de serem gravados na sua pasta privada do Google Drive. Use a mesma conta Google e a mesma senha do cofre no Mac, iPad e iPhone.</p>';
 if(!id||!/^\d+-[\w-]+\.apps\.googleusercontent\.com$/.test(id)){auth.innerHTML=intro+'<p class="notice">A integração está preparada, mas ainda não foi ativada. Siga o guia ATIVAR-GOOGLE-DRIVE.md para criar o ID OAuth público e preencher config.js. Nenhum banco foi criado na sua conta e nenhum dado foi enviado.</p><p>Não coloque senha ou client_secret no código.</p>';return}
 globalThis.CFDrive=new DriveClient(id);globalThis.FinanceStorage=new CloudStore(CFDrive);
 auth.innerHTML=intro+'<button id="connectGoogle" class="primary">Conectar minha conta Google</button><p id="cloudError" role="alert"></p><p class="hint">Permissão limitada aos arquivos criados ou abertos com esta aplicação. Não exige Gmail, contatos ou acesso ao Drive inteiro.</p>';
 try{await load('https://accounts.google.com/gsi/client')}catch(err){fail(err);return}
 document.getElementById('connectGoogle').onclick=()=>{
 // O popup precisa ser solicitado diretamente pelo gesto do usuário (inclusive Safari).
 const connection=CFDrive.authorize();document.getElementById('connectGoogle').disabled=true;
 connection.then(async()=>{const folder=await FinanceStorage.discover();showVault(folder)}).catch(err=>{fail(err);const b=document.getElementById('connectGoogle');if(b)b.disabled=false});
 };
 async function legacy(){let raw,users;try{raw=localStorage.getItem('central-financeira-evolucao-v3')||localStorage.getItem('central-financeira-evolucao-v2');users=localStorage.getItem('central-financeira-evolucao-users-v3')}catch{}
 // Importação explícita, apenas leitura. Não apaga nem modifica a base local anterior.
 if(globalThis.indexedDB){const names=await indexedDB.databases?.();if(names?.some(x=>x.name==='central-financeira-evolucao')){const old=await new Promise((resolve,reject)=>{const req=indexedDB.open('central-financeira-evolucao');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});try{if(old.objectStoreNames.contains('records')){const tx=old.transaction('records'),store=tx.objectStore('records');const read=k=>new Promise((resolve,reject)=>{const req=store.get(k);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});const values=await Promise.all([read('central-financeira-evolucao-v3'),read('central-financeira-evolucao-users-v3')]);raw=values[0]||raw;users=values[1]||users}}finally{old.close()}}}
 if(!raw)throw Error('Nenhuma base local anterior foi encontrada nesta origem. Desmarque a importação e restaure seu backup JSON após abrir o cofre.');const records={'central-financeira-evolucao-v3':JSON.stringify(Core.normalize(JSON.parse(raw)))};if(users)records['central-financeira-evolucao-users-v3']=users;return records;
 }
 function showVault(folder){const create=!folder;auth.innerHTML=intro+`<h2>${create?'Criar cofre privado':'Abrir cofre existente'}</h2><p>${create?'A pasta será criada no seu Drive com o nome indicado. Não compartilhe a pasta.':'Pasta: '+esc(folder.name)}</p><form id="vaultForm">${create?'<label for="folderName">Nome da pasta</label><input id="folderName" required maxlength="100" value="'+esc(config.folderName||'Central Financeira Evolução')+'">':''}<label for="vaultPassword">Senha do cofre — mínimo 12 caracteres</label><input id="vaultPassword" type="password" required minlength="12" autocomplete="${create?'new-password':'current-password'}">${create?'<label for="vaultConfirm">Confirme a senha do cofre</label><input id="vaultConfirm" type="password" required autocomplete="new-password"><label class="checkline"><input type="checkbox" id="importLocal">Importar os dados anteriores deste navegador para o Drive</label><label for="recoverBackup">Ou recuperar de um backup criptografado (.cfvault)</label><input id="recoverBackup" type="file" accept=".cfvault,application/json"><label for="backupPassword">Senha do backup, se diferente da nova senha</label><input id="backupPassword" type="password" autocomplete="current-password"><p class="notice">Guarde esta senha em seu gerenciador de senhas. Ela não é enviada ao Google. Se você a perder, não há recuperação dos dados criptografados.</p>':''}<button id="openVault" class="primary" type="submit">${create?'Criar cofre e gravar no meu Drive':'Abrir meu cofre'}</button><p id="cloudError" role="alert"></p></form><button class="ghost" id="differentAccount">Trocar conta / sair</button>`;
 document.getElementById('differentAccount').onclick=()=>{FinanceStorage.lock();location.reload()};
 document.getElementById('vaultForm').onsubmit=async e=>{e.preventDefault();document.getElementById('openVault').disabled=true;let password=document.getElementById('vaultPassword').value,attemptedWrite=false;try{
 if(create){if(password!==document.getElementById('vaultConfirm').value)throw Error('As senhas do cofre não coincidem.');let records={};const file=document.getElementById('recoverBackup').files?.[0],importLocal=document.getElementById('importLocal').checked;if(file&&importLocal)throw Error('Escolha importar deste navegador OU recuperar um backup.');if(file){const envelope=JSON.parse(await file.text()),oldPassword=document.getElementById('backupPassword').value||password;const oldKey=await VaultCrypto.derive(oldPassword,VaultCrypto.unb64(envelope.salt));records=await VaultCrypto.decrypt(envelope,oldKey)}else if(importLocal)records=await legacy();const name=document.getElementById('folderName').value.trim();if(!name)throw Error('Informe o nome da pasta.');attemptedWrite=true;await FinanceStorage.create(name,password,records)}else await FinanceStorage.unlock(folder,password);
 document.getElementById('vaultPassword').value='';password='';attemptedWrite=true;await load('app.js');const key='central-financeira-evolucao-v3',serialized=JSON.stringify(db);if(FinanceStorage.getItem(key)!==serialized)await FinanceStorage.write(key,serialized);await load('extras.js');FinanceStorage.status();let lastActivity=Date.now();for(const event of ['click','keydown','touchstart'])document.addEventListener(event,()=>{lastActivity=Date.now()},{passive:true});const lockIfIdle=()=>{if(Date.now()-lastActivity>15*60*1000){FinanceStorage.lock();location.reload()}};setInterval(lockIfIdle,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)lockIfIdle()});window.addEventListener('beforeunload',e=>{if(FinanceStorage.state.saving){e.preventDefault();e.returnValue=''}});
 }catch(err){password='';fail(err);const b=document.getElementById('openVault');if(b){b.disabled=attemptedWrite;if(attemptedWrite){const p=document.getElementById('cloudError');p.textContent+=' Não repita a gravação: use Trocar conta / sair e confira o cofre existente.'}}}};
 }
})();
